const isVideoFile = (file: any): boolean => {
  if (!file) return false;
  const type = (file.type || '').toLowerCase();
  const name = (file.name || '').toLowerCase();
  return type.startsWith('video/') || 
         name.endsWith('.mp4') || 
         name.endsWith('.mov') || 
         name.endsWith('.m4v') || 
         name.endsWith('.3gp') || 
         name.endsWith('.webm') || 
         name.endsWith('.avi');
};

const isImageFile = (file: any): boolean => {
  if (!file) return false;
  const type = (file.type || '').toLowerCase();
  const name = (file.name || '').toLowerCase();
  return type.startsWith('image/') || 
         name.endsWith('.jpg') || 
         name.endsWith('.jpeg') || 
         name.endsWith('.png') || 
         name.endsWith('.gif') || 
         name.endsWith('.webp') || 
         name.endsWith('.heic') ||
         name.endsWith('.heif');
};

