const formatPhoneWithCountryCodeMobile = (phone: string | undefined, countryCode: string | undefined): string => {
  if (!phone) return 'N/A';
  const cleanPhone = phone.replace(/\D/g, '');
  let phone10 = cleanPhone;
  let cc = countryCode ? countryCode.trim() : '';

  if (cc) {
    const cleanCc = cc.replace(/\D/g, '');
    if (cleanCc && cleanPhone.startsWith(cleanCc) && cleanPhone.length > cleanCc.length) {
      phone10 = cleanPhone.slice(cleanCc.length);
    }
  } else {
    if (cleanPhone.startsWith('52') && cleanPhone.length === 12) {
      phone10 = cleanPhone.slice(2);
      cc = '+52';
    }
  }

  const formatted = phone10.length === 10
    ? phone10.replace(/^(\d{3})(\d{3})(\d{4})$/, '($1) $2-$3')
    : phone;

  const prefix = cc ? (cc.startsWith('+') ? cc : `+${cc}`) : '+52';
  return `${prefix} ${formatted}`;
};

const getProportionalAdvances = (siblingOrders: RepairOrder[], totalAdvance: number): Record<string, number> => {
  if (siblingOrders.length === 0) return {};
  const totalCost = siblingOrders.reduce((sum, x) => sum + x.cost, 0);
  if (totalCost === 0) {
    const base = Math.floor(totalAdvance / siblingOrders.length);
    const rem = totalAdvance - base * siblingOrders.length;
    const res: Record<string, number> = {};
    siblingOrders.forEach((o, idx) => {
      res[o.id] = base + (idx < rem ? 1 : 0);
    });
    return res;
  }

  const items = siblingOrders.map(o => {
    const exact = (o.cost / totalCost) * totalAdvance;
    const floor = Math.floor(exact);
    const remainder = exact - floor;
    return {
      id: o.id,
      cost: o.cost,
      floor,
      remainder,
    };
  });

  items.sort((a, b) => {
    if (Math.abs(a.remainder - b.remainder) > 1e-9) {
      return b.remainder - a.remainder;
    }
    if (a.cost !== b.cost) {
      return b.cost - a.cost;
    }
    return a.id.localeCompare(b.id);
  });

  const sumFloor = items.reduce((s, item) => s + item.floor, 0);
  const difference = Math.round(totalAdvance - sumFloor);

  const res: Record<string, number> = {};
  items.forEach((item, idx) => {
    res[item.id] = item.floor + (idx < difference ? 1 : 0);
  });

  return res;
};

const getIndividualAdvance = (order: RepairOrder, allOrders: RepairOrder[]): number => {
  if (order.batchId) {
    const siblings = allOrders.filter(x => x.batchId === order.batchId);
    if (siblings.length > 1) {
      const advances = getProportionalAdvances(siblings, order.batchAdvancePayment || 0);
      return advances[order.id] || 0;
    }
  }
  return order.advancePayment || 0;
};


export const formatBarcodeString = (rawCode: any): string => {
  if (rawCode === undefined || rawCode === null) return '';
  let str = String(rawCode).trim();
  if (!str) return '';

  // 1. Detect scientific notation e.g. "8.44726E+12", "8.44726e+12", "1.23E11"
  if (/^[+-]?\d+(\.\d+)?[eE][+-]?\d+$/.test(str)) {
    const num = Number(str);
    if (!isNaN(num) && isFinite(num)) {
      try {
        str = BigInt(Math.round(num)).toString();
      } catch (e) {
        str = num.toLocaleString('fullwide', { useGrouping: false });
      }
    }
  }

  // 2. Detect trailing .0 e.g. "844726123456.0"
  if (/^\d+\.0+$/.test(str)) {
    str = str.split('.')[0];
  }

  // 3. Auto-pad leading zero for standard barcode lengths if Excel truncated a leading zero
  if (/^\d+$/.test(str)) {
    if (str.length === 11) {
      str = '0' + str; // UPC-A
    } else if (str.length === 12) {
      str = '0' + str; // EAN-13 starting with 0
    } else if (str.length === 7) {
      str = '0' + str; // EAN-8/UPC-E
    }
  }

  return str;
};
