const cleanHeaderMobile = (s: string) => s.toLowerCase().trim().replace(/[\s_:-]+/g, '').normalize("NFD").replace(/[\u0300-\u036f]/g, "");

const autoMapHeadersMobile = (headers: string[], isRefacciones?: boolean): Record<string, string> => {
  const mapping: Record<string, string> = {};
  const fields = isRefacciones ? MAPPABLE_FIELDS_REFACCIONES_MOBILE : MAPPABLE_FIELDS_MOBILE;
  
  fields.forEach(field => {
    // 1. Coincidencia exacta o sinónimo directo
    let match = headers.find(h => {
      const cleanedH = cleanHeaderMobile(h);
      return field.synonyms.some(syn => cleanedH === syn);
    });
    
    // 2. Coincidencia por inclusión de subcadena
    if (!match) {
      match = headers.find(h => {
        const cleanedH = cleanHeaderMobile(h);
        return field.synonyms.some(syn => cleanedH.includes(syn) || syn.includes(cleanedH));
      });
    }
    
    if (match) {
      mapping[field.key] = match;
    } else {
      mapping[field.key] = '';
    }
  });
  
  return mapping;
};

const parseNumberCleanMobile = (val: any): number => {
  if (val === undefined || val === null) return 0;
  if (typeof val === 'number') return isNaN(val) ? 0 : val;
  const cleanStr = String(val).replace(/[^0-9.-]/g, '');
  const parsed = parseFloat(cleanStr);
  return isNaN(parsed) ? 0 : parsed;
};

const checkHasWhatsApp = (phone: string | undefined, countryCode: string | undefined, order?: RepairOrder): boolean => {
  if (!phone) return false;
  
  // Priorizar el estado verificado de forma global en la orden (sincronizado desde el escritorio)
  if (order && order.customerHasWhatsApp !== undefined && order.customerHasWhatsApp !== null) {
    return order.customerHasWhatsApp;
  }

  try {
    const cc = countryCode ? countryCode.replace(/\D/g, '') : '52';
    const formatted = formatPhoneForWhatsapp(phone, cc);
    const stored = localStorage.getItem('fixmanager_wa_verified_numbers');
    const verified = stored ? JSON.parse(stored) : {};
    
    // Si la caché indica explícitamente que NO tiene WhatsApp, retornamos false.
    if (verified[formatted] === false) {
      return false;
    }
    // Si es true o si no se ha verificado (undefined, ej. en celular sin sesión activa),
    // asumimos que sí tiene por defecto para permitir el contacto directo.
    return true;
  } catch {
    return true;
  }
};

function SafeImage({
  src,
  alt,
  className,
  fallback
}: {
  src?: string;
  alt: string;
  className: string;
  fallback?: React.ReactNode;
}) {
  const [error, setError] = useState(false);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    setError(false);
    setLoaded(false);
  }, [src]);

  if (!src || error) {
    return fallback ? <>{fallback}</> : (
      <div className={`${className} flex items-center justify-center text-base bg-slate-100 dark:bg-zinc-800 text-slate-500 dark:text-zinc-400 select-none shrink-0`}>
        📦
      </div>
    );
  }

  return (
    <img
      src={src}
      alt={alt}
      loading="lazy"
      onError={() => setError(true)}
      onLoad={() => setLoaded(true)}
      className={`${className} transition-opacity duration-300 ${loaded ? 'opacity-100' : 'opacity-0'}`}
    />
  );
}

