  const convertHtmlToEscPos = (htmlStr: string, isLabel = false, paperSize: '80mm' | '58mm' = '80mm'): Uint8Array => {
    const parser = new DOMParser();
    const doc = parser.parseFromString(htmlStr, 'text/html');
    const maxChar = paperSize === '58mm' ? 32 : 48;

    const encoder = new TextEncoder();
    const bytesList: number[] = [];

    // Comandos ESC/POS básicos:
    // Inicializar: ESC @ (0x1B, 0x40)
    bytesList.push(0x1B, 0x40);

    // Normalizador de texto para remover acentos y eñes
    const sanitizeText = (text: string): string => {
      return text
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/ñ/g, 'n')
        .replace(/Ñ/g, 'N');
    };

    const addLine = (text: string, align: 'left' | 'center' | 'right' = 'left') => {
      const cleanText = sanitizeText(text);
      // ESC a n (Alineación: 0 = Izq, 1 = Centro, 2 = Der)
      const alignCmd = align === 'center' ? 1 : align === 'right' ? 2 : 0;
      bytesList.push(0x1B, 0x61, alignCmd);

      const textBytes = encoder.encode(cleanText + '\n');
      bytesList.push(...Array.from(textBytes));
    };

    const walk = (node: Node) => {
      if (node.nodeType === Node.TEXT_NODE) {
        const txt = node.textContent?.trim();
        if (txt) {
          let align: 'left' | 'center' | 'right' = 'left';
          let parent = node.parentElement;
          while (parent) {
            const style = parent.getAttribute('style') || '';
            const className = parent.className || '';
            if (style.includes('text-align: center') || className.includes('text-center') || parent.tagName === 'CENTER') {
              align = 'center';
              break;
            } else if (style.includes('text-align: right') || className.includes('text-right')) {
              align = 'right';
              break;
            }
            parent = parent.parentElement;
          }
          
          if (txt.includes('---') || txt.includes('===') || txt.includes('***')) {
            addLine('-'.repeat(maxChar), 'center');
          } else {
            addLine(txt, align);
          }
        }
      } else if (node.nodeType === Node.ELEMENT_NODE) {
        const el = node as Element;
        
        if (el.tagName === 'TABLE') {
          const rows = el.querySelectorAll('tr');
          rows.forEach(row => {
            const cols = row.querySelectorAll('td, th');
            if (cols.length === 2) {
              const col1 = sanitizeText(cols[0].textContent?.trim() || '');
              const col2 = sanitizeText(cols[1].textContent?.trim() || '');
              const dotsCount = maxChar - col1.length - col2.length;
              const line = col1 + (dotsCount > 0 ? ' '.repeat(dotsCount) : ' ') + col2;
              bytesList.push(0x1B, 0x61, 0);
              bytesList.push(...Array.from(encoder.encode(line + '\n')));
            } else if (cols.length >= 3) {
              const desc = sanitizeText(cols[0].textContent?.trim() || '');
              const qty = sanitizeText(cols[1].textContent?.trim() || '');
              const price = sanitizeText(cols[2].textContent?.trim() || '');
              
              const priceWidth = paperSize === '58mm' ? 8 : 12;
              const qtyWidth = paperSize === '58mm' ? 4 : 6;
              const descWidth = maxChar - priceWidth - qtyWidth;
              
              const padRight = (str: string, length: number) => str.padEnd(length).slice(0, length);
              const padLeft = (str: string, length: number) => str.padStart(length).slice(0, length);
              
              const line = padRight(qty, qtyWidth) + padRight(desc, descWidth) + padLeft(price, priceWidth);
              bytesList.push(0x1B, 0x61, 0);
              bytesList.push(...Array.from(encoder.encode(line + '\n')));
            } else {
              const txt = sanitizeText(row.textContent?.trim() || '');
              if (txt) addLine(txt);
            }
          });
          return;
        }
        
        el.childNodes.forEach(walk);
      }
    };

    walk(doc.body);

    // Alimentar papel y cortar:
    bytesList.push(0x0A, 0x0A, 0x0A, 0x0A);
    bytesList.push(0x1D, 0x56, 0x42, 0x00);

    return new Uint8Array(bytesList);
  };

  const sendBluetoothBytes = async (deviceId: string, bytes: Uint8Array, isLabel = false) => {
    try {
      triggerPrintToast('📡', 'Conectando Impresora', 'Estableciendo comunicación Bluetooth...', '#3b82f6');
      await BleClient.initialize();
      await BleClient.connect(deviceId, () => {
        console.log('[BleClient] Impresora desconectada');
      });

      triggerPrintToast('⚙️', 'Preparando Dispositivo', 'Buscando canal de datos...', '#3b82f6');
      const services = await BleClient.getServices(deviceId);
      let targetServiceUuid = '';
      let targetCharacteristicUuid = '';

      for (const s of services) {
        if (s.characteristics) {
          for (const c of s.characteristics) {
            if (c.properties && (c.properties.write || c.properties.writeWithoutResponse)) {
              targetServiceUuid = s.uuid;
              targetCharacteristicUuid = c.uuid;
              break;
            }
          }
        }
        if (targetCharacteristicUuid) break;
      }

      if (!targetCharacteristicUuid) {
        throw new Error('No se detectó el canal de escritura en la impresora vinculada.');
      }

      triggerPrintToast('🖨️', 'Transmitiendo Datos', 'Enviando ticket a cabezal térmico...', '#3b82f6');

      const chunkSize = 20;
      for (let i = 0; i < bytes.length; i += chunkSize) {
        const chunk = bytes.slice(i, i + chunkSize);
        await BleClient.writeWithoutResponse(deviceId, targetServiceUuid, targetCharacteristicUuid, new DataView(chunk.buffer));
        await new Promise(resolve => setTimeout(resolve, 15));
      }

      triggerPrintToast('✅', 'Impreso con Éxito', isLabel ? 'Etiqueta impresa por Bluetooth' : 'Ticket impreso por Bluetooth', '#10b981');
    } catch (err: any) {
      console.error('[BleClient] Error:', err);
      triggerPrintToast('❌', 'Error de Impresión', err?.message || 'Fallo al transmitir por Bluetooth.', '#dc2626');
    } finally {
      try {
        await BleClient.disconnect(deviceId);
      } catch (_) {}
    }
  };

  const printMobileHtml = (htmlStr: string, isLabel = false) => {
    // 1. Obtener la impresora activa
    const activePrinterName = isLabel
      ? (labelConnectedPrinter || config.labelPrinterBrand)
      : (ticketConnectedPrinter || config.ticketPrinterBrand || connectedPrinterName);

    // 2. Si no hay impresora configurada, mostramos toast arriba y no hacemos nada más
    if (!activePrinterName || activePrinterName.trim() === '' || activePrinterName.toLowerCase().includes('ninguna') || activePrinterName.toLowerCase().includes('sin configurar')) {
      triggerPrintToast('⚠️', 'Impresora no configurada', 'No hay impresora configurada en ajustes.', '#f59e0b');
      return;
    }

    // 3. Imprimir directo por Bluetooth si el modo está configurado
    if (mobilePrintMode === 'bluetooth') {
      const printerObj = discoveredPrinters.find(p => p.name === activePrinterName && p.type === 'bluetooth');
      const deviceId = printerObj?.address || activePrinterName;

      if (deviceId) {
        const paperSize = mobilePaperWidth === '58mm' ? '58mm' : '80mm';
        const bytes = convertHtmlToEscPos(htmlStr, isLabel, paperSize);
        sendBluetoothBytes(deviceId, bytes, isLabel);
        return;
      }
    }

    // 4. Si no es Bluetooth, fallback de impresión nativa (AirPrint)
    try {
      const iframe = document.createElement('iframe');
      iframe.style.position = 'fixed';
      iframe.style.left = '-9999px';
      iframe.style.top = '0px';
      iframe.style.width = isLabel ? '350px' : '400px';
      iframe.style.height = '800px';
      iframe.style.border = 'none';
      iframe.style.opacity = '0';
      iframe.style.pointerEvents = 'none';
      document.body.appendChild(iframe);

      const iframeDoc = iframe.contentWindow?.document || iframe.contentDocument;
      if (iframeDoc) {
        iframeDoc.open();
        iframeDoc.write(htmlStr);
        iframeDoc.close();
        
        setTimeout(() => {
          try {
            iframe.contentWindow?.focus();
            iframe.contentWindow?.print();
            setTimeout(() => {
              try { document.body.removeChild(iframe); } catch (_) {}
            }, 2000);
          } catch (e) {
            console.error('Error imprimiendo en iframe móvil:', e);
            try { document.body.removeChild(iframe); } catch (_) {}
          }
        }, 300);
      } else {
        window.print();
      }

      triggerPrintToast(
        isLabel ? '🏷️' : '🖨️',
        isLabel ? 'Etiqueta de Equipo' : 'Ticket de Venta / Servicio',
        isLabel ? `Etiqueta enviada a ${activePrinterName}` : `Ticket enviado a ${activePrinterName}`,
        '#10b981'
      );
    } catch (err) {
      console.error('Error procesando impresión móvil:', err);
      triggerPrintToast('❌', 'Error de Impresión', 'Ocurrió un problema al enviar a la impresora.', '#dc2626');
    }
  };

  useEffect(() => {
    const handleShowWhatsappModal = (e: Event) => {
      const detail = (e as CustomEvent).detail;
      if (!detail) return;

      const { phone, text, htmlForImage, countryCode } = detail;

      // En móviles, en lugar de usar el modal de escritorio, usamos el bottom sheet móvil nativo
      if (htmlForImage) {
        setWhatsappPromptModalData({
          ticketHtml: htmlForImage,
          phone,
          countryCode: countryCode || '52',
          customMsg: text
        });
        return;
      }

      const cc = countryCode ? countryCode.replace('+', '') : (config.whatsappDefaultCountryCode || '52');
      const formattedPhone = formatPhoneForWhatsapp(phone, cc);
      const encodedText = encodeURIComponent(text);

      if (formattedPhone) {
        triggerPrintToast('💬', 'Envío de WhatsApp', 'Abriendo chat para enviar actualización de estado...');

        const nativeScheme = `whatsapp://send?phone=${formattedPhone}&text=${encodedText}`;
        const waMeUrl = `https://wa.me/${formattedPhone}?text=${encodedText}`;

        setTimeout(() => {
          window.location.href = nativeScheme;
          setTimeout(() => {
            if (!document.hidden) {
              window.location.href = waMeUrl;
            }
          }, 1200);
        }, 1500);
      }
    };
    window.addEventListener('show-whatsapp-modal', handleShowWhatsappModal);
    return () => window.removeEventListener('show-whatsapp-modal', handleShowWhatsappModal);
  }, [config, triggerPrintToast]);

  const handleLogoFileUpload = (key: string, file: File) => {
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      const src = e.target?.result as string;
      if (!src) return;

      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => {
        // Preservar la proporción original (aspect ratio) sin recortar esquinas o nombres
        const w = img.naturalWidth || img.width;
        const h = img.naturalHeight || img.height;
        const targetMaxSize = 480;

        let newW = w;
        let newH = h;
        if (w > h) {
          if (w > targetMaxSize) {
            newW = targetMaxSize;
            newH = Math.round((h * targetMaxSize) / w);
          }
        } else {
          if (h > targetMaxSize) {
            newH = targetMaxSize;
            newW = Math.round((w * targetMaxSize) / h);
          }
        }

        const canvas = document.createElement('canvas');
        canvas.width = newW;
        canvas.height = newH;
        const ctx = canvas.getContext('2d');

        if (ctx) {
          ctx.fillStyle = '#ffffff';
          ctx.fillRect(0, 0, newW, newH);
          ctx.imageSmoothingEnabled = true;
          ctx.imageSmoothingQuality = 'high';
          ctx.drawImage(img, 0, 0, newW, newH);

          const compressedBase64 = canvas.toDataURL('image/jpeg', 0.85);

          setEditableConfig(prev => {
            const updated: any = { ...prev, [key]: compressedBase64 };
            if (key === 'customLogo' || key === 'logoUrl') {
              updated.logoUrl = compressedBase64;
              updated.customLogo = compressedBase64;
            }
            if (key === 'quoteSecondLogoUrl' || key === 'quotationLogoUrl') {
              updated.quoteSecondLogoUrl = compressedBase64;
              updated.quotationLogoUrl = compressedBase64;
            }
            return updated;
          });
          triggerPrintToast('📸', 'Logo Completo', 'Imagen adaptada preservando formato horizontal HD');
        }
      };
      img.src = src;
    };
    reader.readAsDataURL(file);
  };
  const [ticketModalOrder, setTicketModalOrder] = useState<RepairOrder | null>(null);
  const [ticketModalIsBatch, setTicketModalIsBatch] = useState<boolean>(false);
  const [ticketSheetStartY, setTicketSheetStartY] = useState<number | null>(null);
  const [ticketSheetTranslateY, setTicketSheetTranslateY] = useState<number>(0);
  const [showPrinterQuickHubModal, setShowPrinterQuickHubModal] = useState(false);
  const [quickHubTranslateY, setQuickHubTranslateY] = useState(0);
  const [quickHubStartY, setQuickHubStartY] = useState<number | null>(null);

  const [mobilePaperWidth, setMobilePaperWidth] = useState<'80mm' | '58mm' | 'media-carta'>(config.posPaperWidth || (config as any).paperWidth || '80mm');
  const [mobilePrinterPresetId, setMobilePrinterPresetId] = useState<string>(config.selectedPrinterProfileId || 'xprinter-xp-n160ii');
  
  // Estados para Impresión de Etiquetas de Productos con Copias
  const [printProductLabelItem, setPrintProductLabelItem] = useState<InventoryItem | null>(null);
  const [productLabelCopies, setProductLabelCopies] = useState<number>(1);
  const [productLabelStyle, setProductLabelStyle] = useState<'standard' | 'vitrina' | 'qr' | 'technical'>('standard');
  const [productLabelSheetStartY, setProductLabelSheetStartY] = useState<number | null>(null);
  const [productLabelSheetTranslateY, setProductLabelSheetTranslateY] = useState<number>(0);

  // Estados para Escáner Real de Impresoras Bluetooth / Wi-Fi y Márgenes
  const [printerSettingsTab, setPrinterSettingsTab] = useState<'scan' | 'profile'>('scan');
  const [mobilePrintMode, setMobilePrintMode] = useState<'system' | 'bluetooth' | 'network'>(() => {
    return (localStorage.getItem('fixmanager_mobile_print_mode') as any) || 'system';
  });
  const sanitizePrinterName = (name: string | null): string => {
    if (!name) return '';
    const lower = name.toLowerCase();
    const nonPrinters = [
      'airpods', 'headphone', 'headset', 'buds', 'beats', 'speaker', 'tv', 'watch', 'iphone', 'ipad', 'macbook',
      '192.168.1.105', '192.168.1.110', 'impresora red (192.168.1.105)', 'etiquetadora red (192.168.1.110)'
    ];
    if (nonPrinters.some(np => lower.includes(np))) {
      try {
        localStorage.removeItem('fixmanager_mobile_ticket_printer');
        localStorage.removeItem('fixmanager_mobile_label_printer');
        localStorage.removeItem('fixmanager_mobile_connected_printer');
      } catch(e) {}
      return '';
    }
    return name;
  };

  const [ticketConnectedPrinter, setTicketConnectedPrinter] = useState<string>(() => {
    const saved = localStorage.getItem('fixmanager_mobile_ticket_printer');
    const clean = sanitizePrinterName(saved);
    if (saved && !clean) localStorage.removeItem('fixmanager_mobile_ticket_printer');
    return clean;
  });
  const [labelConnectedPrinter, setLabelConnectedPrinter] = useState<string>(() => {
    const saved = localStorage.getItem('fixmanager_mobile_label_printer');
    const clean = sanitizePrinterName(saved);
    if (saved && !clean) localStorage.removeItem('fixmanager_mobile_label_printer');
    return clean;
  });
  const [reportConnectedPrinter, setReportConnectedPrinter] = useState<string>(() => {
    const saved = localStorage.getItem('fixmanager_mobile_report_printer');
    const clean = sanitizePrinterName(saved);
    if (saved && !clean) localStorage.removeItem('fixmanager_mobile_report_printer');
    return clean;
  });
  const [connectedPrinterName, setConnectedPrinterName] = useState<string>(() => {
    return ticketConnectedPrinter || labelConnectedPrinter || reportConnectedPrinter || '';
  });
  const [printerIpAddress, setPrinterIpAddress] = useState<string>(() => {
    return localStorage.getItem('fixmanager_mobile_printer_ip') || '';
  });
  const [ticketMarginOffset, setTicketMarginOffset] = useState<number>(() => {
    return Number(localStorage.getItem('fixmanager_ticket_margin_offset') || 0);
  });
  const [isScanningPrinters, setIsScanningPrinters] = useState(false);
  const [showInlinePrinterScanner, setShowInlinePrinterScanner] = useState(false);
  const [showAllBTDevices, setShowAllBTDevices] = useState(false);
  const [discoveredPrinters, setDiscoveredPrinters] = useState<Array<{ name: string; type: 'bluetooth' | 'network' | 'system'; address: string; connected?: boolean }>>(() => {
    try {
      localStorage.removeItem('fixmanager_mobile_discovered_printers');
    } catch (e) {}
    return [];
  });

  const runBluetoothDeviceScan = async (targetCategory: 'ticket' | 'label' = 'ticket') => {
    setIsScanningPrinters(true);

    const isPrinterName = (name: string) => {
      if (showAllBTDevices) return true;
      const lower = name.toLowerCase();
      const printerKeywords = ['pos', 'thermal', 'printer', 'xp', 'pt', 'mpt', 'rp', 'bt-', 'tsp', 'epson', 'star', 'zebra', 'bixolon', 'citizen', 'godex', 'tsc', 'hprt', 'gprinter', 'label'];
      return printerKeywords.some(kw => lower.includes(kw));
    };

    const activeName = targetCategory === 'ticket' ? ticketConnectedPrinter : labelConnectedPrinter;
    setDiscoveredPrinters(prev => prev.filter(p => p.name === activeName && isPrinterName(p.name)));

    let scanStarted = false;

    try {
      await BleClient.initialize();
      await BleClient.requestLEScan(
        { allowDuplicates: false },
        (result) => {
          if (result && result.device) {
            const devName = result.device.name || result.localName;
            if (devName && devName.trim() && isPrinterName(devName.trim())) {
              const newP = {
                name: devName.trim(),
                type: 'bluetooth' as const,
                address: result.device.deviceId || 'Bluetooth LE'
              };
              setDiscoveredPrinters(prev => {
                const filtered = prev.filter(p => p.name !== newP.name);
                return [newP, ...filtered];
              });
            }
          }
        }
      );
      scanStarted = true;
      setTimeout(async () => {
        try { await BleClient.stopLEScan(); } catch (e) {}
        setIsScanningPrinters(false);
      }, 5000);
    } catch (bleErr) {}

    if (!scanStarted) {
      if (typeof navigator !== 'undefined' && (navigator as any).bluetooth) {
        try {
          const reqOptions = showAllBTDevices
            ? {
                acceptAllDevices: true,
                optionalServices: ['00001101-0000-1000-8000-00805f9b34fb', '000018f0-0000-1000-8000-00805f9b34fb', '0000ff00-0000-1000-8000-00805f9b34fb']
              }
            : {
                filters: [
                  { services: ['00001101-0000-1000-8000-00805f9b34fb'] },
                  { services: ['000018f0-0000-1000-8000-00805f9b34fb'] },
                  { namePrefix: 'POS' },
                  { namePrefix: 'pos' },
                  { namePrefix: 'Thermal' },
                  { namePrefix: 'thermal' },
                  { namePrefix: 'Printer' },
                  { namePrefix: 'printer' },
                  { namePrefix: 'XP' },
                  { namePrefix: 'xp' },
                  { namePrefix: 'PT' },
                  { namePrefix: 'MPT' },
                  { namePrefix: 'RP' },
                  { namePrefix: 'BT-' },
                  { namePrefix: 'TSP' },
                  { namePrefix: 'Epson' },
                  { namePrefix: 'Star' },
                  { namePrefix: 'Zebra' }
                ],
                optionalServices: ['00001101-0000-1000-8000-00805f9b34fb', '000018f0-0000-1000-8000-00805f9b34fb']
              };
          const device = await (navigator as any).bluetooth.requestDevice(reqOptions);
          if (device && (device.name || device.id)) {
            const devName = device.name || `Impresora BT (${device.id ? device.id.slice(-4) : 'BT'})`;
            const newP = {
              name: devName,
              type: 'bluetooth' as const,
              address: device.id || 'Bluetooth SPP'
            };
            setDiscoveredPrinters(prev => [newP, ...prev.filter(p => p.name !== newP.name)]);
            if (targetCategory === 'ticket') {
              setTicketConnectedPrinter(devName);
              setConnectedPrinterName(devName);
              localStorage.setItem('fixmanager_mobile_ticket_printer', devName);
              localStorage.setItem('fixmanager_mobile_connected_printer', devName);
            } else {
              setLabelConnectedPrinter(devName);
              localStorage.setItem('fixmanager_mobile_label_printer', devName);
            }
            triggerPrintToast('🔵', 'Dispositivo Vinculado', devName);
          }
        } catch (e) {}
      }
      setIsScanningPrinters(false);
    }
  };

  const closeCreateWizardSheet = (confirmClose = true, forceDiscard = false) => {
    if (typeof document !== 'undefined' && document.activeElement && typeof (document.activeElement as HTMLElement).blur === 'function') {
      (document.activeElement as HTMLElement).blur();
    }
    if (isClosingCreateWizard) return;

    const hasWizardData = 
      wizardStep > 0 || 
      Boolean(wizardDeviceBrand.trim()) || 
      Boolean(wizardDeviceModel.trim()) || 
      Boolean(wizardFaultDescription.trim()) || 
      Boolean(wizardSelectedClient) || 
      Boolean(wizardNewClientName.trim()) ||
      Boolean(wizardDeviceSearchQuery.trim());

    if (confirmClose && !forceDiscard && hasWizardData) {
      setShowConfirmDiscardWizardSheet(true);
      return;
    }

    setShowConfirmDiscardWizardSheet(false);
    setIsClosingCreateWizard(true);
    setCreateWizardDragY(0);
    setCreateWizardStartY(null);
    setTimeout(() => {
      setShowCreateWizard(false);
      setIsClosingCreateWizard(false);
      setCreateWizardDragY(0);
    }, 300);
  };

  const shouldAllowSheetDrag = (e: React.TouchEvent) => {
    const target = e.target as HTMLElement;
    if (target.closest('input, textarea, select, button, label, a, [data-no-drag]')) {
      return false;
    }
    const container = target.closest('.overflow-y-auto');
    if (container && container.scrollTop > 0) {
      return false;
    }
    return true;
  };

  const handleItemSheetTouchStart = (e: React.TouchEvent) => {
    if (!shouldAllowSheetDrag(e)) {
      setItemSheetStartY(null);
      return;
    }
    setItemSheetStartY(e.touches[0].clientY);
  };

  const handleItemSheetTouchMove = (e: React.TouchEvent) => {
    if (itemSheetStartY === null) return;
    const deltaY = e.touches[0].clientY - itemSheetStartY;
    if (deltaY > 0) {
      setItemSheetDragY(deltaY);
    }
  };

  const handleItemSheetTouchEnd = () => {
    if (itemSheetDragY > 100) {
      closeItemSheet();
    } else {
      setItemSheetDragY(0);
    }
    setItemSheetStartY(null);
  };

  const handleRefaccionSheetTouchStart = (e: React.TouchEvent) => {
    if (!shouldAllowSheetDrag(e)) {
      setRefaccionSheetStartY(null);
      return;
    }
    setRefaccionSheetStartY(e.touches[0].clientY);
  };

  const handleRefaccionSheetTouchMove = (e: React.TouchEvent) => {
    if (refaccionSheetStartY === null) return;
    const deltaY = e.touches[0].clientY - refaccionSheetStartY;
    if (deltaY > 0) {
      setRefaccionSheetDragY(deltaY);
    }
  };

  const handleRefaccionSheetTouchEnd = () => {
    if (refaccionSheetDragY > 100) {
      closeRefaccionSheet();
    } else {
      setRefaccionSheetDragY(0);
    }
    setRefaccionSheetStartY(null);
  };

  const handleAddToCart = (item: InventoryItem) => {
    setPosCart(prev => {
      const existing = prev.find(c => c.item.id === item.id);
      if (existing) {
        return prev.map(c => c.item.id === item.id ? { ...c, quantity: c.quantity + 1 } : c);
      }
      return [...prev, { item, quantity: 1 }];
    });
  };

  const playScanBeep = (type: 'success' | 'error' = 'success') => {
    if ((config as any).playSounds === false) return;
    try {
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
      if (!AudioCtx) return;
      const ctx = new AudioCtx();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      osc.type = 'sine';
      
      if (type === 'success') {
        // Tono agudo y limpio de escáner comercial (1400 Hz por 70ms)
        osc.frequency.setValueAtTime(1400, ctx.currentTime);
        gain.gain.setValueAtTime(0.18, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.08);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(ctx.currentTime);
        osc.stop(ctx.currentTime + 0.08);
      } else {
        // Tono de error grave
        osc.frequency.setValueAtTime(350, ctx.currentTime);
        gain.gain.setValueAtTime(0.2, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.18);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(ctx.currentTime);
        osc.stop(ctx.currentTime + 0.18);
      }
    } catch (e) {
      console.warn("AudioContext beep error:", e);
    }
  };

  const handleBarCodeScanned = (scannedCode: string) => {
    const code = scannedCode.trim().toLowerCase();
    if (!code) return;

    // Buscar en inventario por código, ID o barcode
    const match = (inventory || []).find((item) => {
      const itemCode = (item.code || '').trim().toLowerCase();
      const itemId = (item.id || '').trim().toLowerCase();
      const itemName = (item.name || '').trim().toLowerCase();
      return itemCode === code || itemId === code || itemName === code;
    });

    if (match) {
      playScanBeep('success');
      handleAddToCart(match);
      setPosSearchQuery(match.code || match.name);
      setScanStatusMsg({ type: 'success', text: `✓ ¡Agregado: ${match.name}!` });
    } else {
      playScanBeep('error');
      setScanStatusMsg({ type: 'error', text: `⚠️ Código "${scannedCode}" no encontrado` });
    }

    setTimeout(() => {
      setScanStatusMsg(null);
    }, 3000);
  };

  const [trackedBarcodeBox, setTrackedBarcodeBox] = useState<{ x: number; y: number; width: number; height: number } | null>(null);

  useEffect(() => {
    let isSubscribed = true;

    if (isScanningBarcode) {
      const elementId = "barcode-scanner-view";
      const timer = setTimeout(() => {
        if (!isSubscribed) return;
        try {
          const scannerInstance = new Html5Qrcode(elementId, false);
          html5QrcodeRef.current = scannerInstance;
          scannerInstance.start(
            { facingMode: "environment" },
            {
              fps: 10,
              aspectRatio: 1.0,
            },
            (decodedText, decodedResult) => {
              if (isSubscribed) {
                // RASTREO DINÁMICO DE CÓDIGO DE BARRAS (ESTILO SAM'S CLUB)
                if (decodedResult && (decodedResult as any).result?.points) {
                  const pts = (decodedResult as any).result.points;
                  if (Array.isArray(pts) && pts.length > 0) {
                    const xs = pts.map((p: any) => p.x);
                    const ys = pts.map((p: any) => p.y);
                    const minX = Math.min(...xs);
                    const maxX = Math.max(...xs);
                    const minY = Math.min(...ys);
                    const maxY = Math.max(...ys);

                    const videoElem = document.querySelector('#barcode-scanner-view video') as HTMLVideoElement;
                    if (videoElem && videoElem.videoWidth && videoElem.videoHeight) {
                      const scaleX = 100 / videoElem.videoWidth;
                      const scaleY = 100 / videoElem.videoHeight;
                      setTrackedBarcodeBox({
                        x: Math.max(2, minX * scaleX),
                        y: Math.max(2, minY * scaleY),
                        width: Math.min(96, Math.max(25, (maxX - minX) * scaleX)),
                        height: Math.min(96, Math.max(20, (maxY - minY) * scaleY))
                      });
                    }
                  }
                } else {
                  // Fallback: Caja rastreadora amarilla destacada sobre el área escaneada
                  setTrackedBarcodeBox({ x: 15, y: 20, width: 70, height: 60 });
                }

                handleBarCodeScanned(decodedText);

                // Desvanecer el marco rastreador amarillo después de 1.5s
                setTimeout(() => {
                  if (isSubscribed) setTrackedBarcodeBox(null);
                }, 1500);
              }
            },
            () => {}
          ).catch((err) => {
            console.warn("Camera access error:", err);
          });
        } catch (err) {
          console.warn("Scanner initialization error:", err);
        }
      }, 100);

      return () => {
        isSubscribed = false;
        clearTimeout(timer);
        if (html5QrcodeRef.current) {
          if (html5QrcodeRef.current.isScanning) {
            html5QrcodeRef.current.stop().catch((e) => console.error("Error stopping scanner:", e));
          }
          html5QrcodeRef.current = null;
        }
        setIsFlashOn(false);
        setShowManualCodeInput(false);
        setTrackedBarcodeBox(null);
      };
    }
  }, [isScanningBarcode]);

  const isPersonalMode = (config.workshopMode ?? 'personal') === 'personal';

  // --- ESTADOS PARA EL ASISTENTE DE RECEPCIÓN (NUEVA ORDEN - 4 ETAPAS) ---
  const [showCreateWizard, setShowCreateWizard] = useState(false);
  const [wizardStep, setWizardStep] = useState<number>(0);
  
  // Etapa 1 (Paso 0): Equipo / Dispositivo
  const [wizardDeviceSearchQuery, setWizardDeviceSearchQuery] = useState('');
  const [wizardIsRegisteringNewDevice, setWizardIsRegisteringNewDevice] = useState(false);
  const [wizardDeviceType, setWizardDeviceType] = useState('Celular');
  const [wizardDeviceBrand, setWizardDeviceBrand] = useState('');
  const [wizardDeviceModel, setWizardDeviceModel] = useState('');
  const [wizardDeviceModelNumber, setWizardDeviceModelNumber] = useState('');
  const [wizardPinType, setWizardPinType] = useState<'none' | 'pin' | 'pattern'>('none');
  const [wizardPinValue, setWizardPinValue] = useState('');
  const wizardPinInputRef = React.useRef<HTMLInputElement | null>(null);
  const [wizardPatternNodes, setWizardPatternNodes] = useState<number[]>([]);
  const patternSvgRef = React.useRef<SVGSVGElement | null>(null);
  const [isDraggingPattern, setIsDraggingPattern] = useState(false);
  const [patternTouchPos, setPatternTouchPos] = useState<{ x: number; y: number } | null>(null);
  const [wizardSelectedAccessories, setWizardSelectedAccessories] = useState<string[]>([]);
  const [showAccessoriesAccordion, setShowAccessoriesAccordion] = useState(false);
  const [wizardInternetDeviceSuggestions, setWizardInternetDeviceSuggestions] = useState<any[]>([]);
  const [wizardSelectedParts, setWizardSelectedParts] = useState<{ name: string; cost: number; price: number; refaccionId: string; fromStock: boolean }[]>([]);
  const [wizardPartsSearchQuery, setWizardPartsSearchQuery] = useState<string>('');
  const [wizardIsEquipmentCollapsed, setWizardIsEquipmentCollapsed] = useState<boolean>(true);
  const [wizardIsAssignCollapsed, setWizardIsAssignCollapsed] = useState<boolean>(true);
