                          <div className={`p-3 rounded-xl border flex items-center justify-between ${
                            isLight ? 'bg-emerald-50 border-emerald-200 text-emerald-900' : 'bg-emerald-950/20 border-emerald-800/40 text-emerald-300'
                          }`}>
                            <div>
                              <p className="text-[8.5px] font-black uppercase tracking-wider opacity-75">Servicio Confirmado</p>
                              <p className="text-xs font-black uppercase">{wizardFaultDescription} ({config.currencySymbol || '$'}{wizardCost})</p>
                            </div>
                            <button
                              type="button"
                              onClick={() => {
                                setWizardSelectedServiceName(wizardFaultDescription);
                                setWizardServicePrice(wizardCost);
                                setWizardIsConfirmingServicePrice(true);
                              }}
                              className="text-[9px] font-bold uppercase underline cursor-pointer"
                            >
                              Editar Precio
                            </button>
                          </div>
