                            <button
                              type="button"
                              onClick={() => {
                                setWizardClientQuery('');
                                setWizardSelectedClient(null);
                              }}
                              className="absolute right-3 top-1/2 -translate-y-1/2 text-zinc-400 hover:text-white font-black text-xs cursor-pointer"
                            >
                              ✕
                            </button>
