                                      id: 'TKT-158',
                                      customerName: 'HUGO GARCIA SANCHEZ',
                                      customerPhone: '3512595738',
                                      customerCountryCode: '+52',
                                      deviceBrand: 'APPLE',
                                      deviceModel: 'IPHONE 11',
                                      deviceModelNumber: 'A2111',
